// Embedding helpers shared by WF-21 (embed each new feed item), WF-31 (embed
// the search topic) and scripts/backfill-embeddings.js.
//
// Qwen3-Embedding-0.6B, picked over nomic-embed-text-v1.5 on 2026-10-10 by
// measurement: nomic scored an absent topic ("quantum computing", 0.69) above
// a real one (0.64), so no cutoff could say "nothing found"; Qwen3 put every
// real topic >= 0.55 and every absent one <= 0.42. It is also multilingual —
// the feed carries Bengali items.
//
// Qwen3 is asymmetric: queries carry a task instruction, documents carry none.

const EMBED_MODEL = 'text-embedding-qwen3-embedding-0.6b';
const EMBED_DIM = 1024;
const QUERY_INSTRUCT = 'Given a topic, retrieve news articles and reports about that topic';

// What a feed item "is about" — the model's own summary, not the raw page.
// Raw pages average ~28k chars of nav and boilerplate.
function docText(item) {
  const it = item || {};
  const tags = Array.isArray(it.tags) ? it.tags.filter(Boolean).join(', ') : '';
  const parts = [it.title, it.summary, it.angle, tags ? 'Tags: ' + tags : '']
    .map((s) => (s == null ? '' : String(s).trim())).filter(Boolean);
  return parts.join('\n').slice(0, 6000);
}

function queryText(q) {
  return 'Instruct: ' + QUERY_INSTRUCT + '\nQuery: ' + String(q == null ? '' : q).trim();
}

// pgvector literal. Every value is checked to be a finite number, which is
// also what makes it safe to splice into SQL text.
function vectorLiteral(vec) {
  if (!Array.isArray(vec) || vec.length !== EMBED_DIM) {
    throw new Error('embedding must be an array of ' + EMBED_DIM + ' numbers, got ' +
      (Array.isArray(vec) ? vec.length : typeof vec));
  }
  for (const v of vec) {
    if (typeof v !== 'number' || !Number.isFinite(v)) throw new Error('embedding contains a non-finite value');
  }
  return '[' + vec.join(',') + ']';
}

// Pure helpers for WF-31 query_feed: topic fan-out, item references, and the
// vector packing that gets embeddings through n8n's queryReplacement.
//
// queryReplacement splits its value on commas, so nothing passed through it
// may contain one: topics have commas swapped for spaces, and vectors travel
// space-separated (SQL turns them back into a pgvector literal).

const MAX_TOPICS = 3;
// Swept 2026-10-10 with scripts/eval-search.js (39 cases, Qwen3-Embedding-0.6B):
//   keyword only  25/31 found, 6/6 absent, 68% precision
//   0.42          31/31        6/6         69%
//   0.45          31/31        6/6         71%   <- shipped
//   0.48          30/31        6/6         73%   (loses "AI that can buy things for you")
//   0.52          28/31        6/6         75%
// Re-tune with SIM_CUTOFF=x node scripts/build-wf31.js + the eval, not by feel.
const SIM_CUTOFF = 0.45;

// "bangladesh bank | nigeria ai" -> ['bangladesh bank', 'nigeria ai'].
// '|' and ';' both separate; duplicates and empties drop; at most 3.
function parseTopics(tag) {
  const seen = new Set();
  const out = [];
  for (const raw of String(tag == null ? '' : tag).split(/[|;]/)) {
    const t = raw.replace(/,/g, ' ').replace(/\s+/g, ' ').trim();
    const key = t.toLowerCase();
    if (!t || seen.has(key)) continue;
    seen.add(key);
    out.push(t);
    if (out.length === MAX_TOPICS) break;
  }
  return out;
}

// "3", "#3", "no. 3", "item 3" -> 3. Anything else -> null.
function parseItemRef(item) {
  const m = String(item == null ? '' : item).match(/^\s*(?:#|no\.?\s*|item\s*|number\s*)?(\d{1,3})\s*$/i);
  if (!m) return null;
  const n = Number(m[1]);
  return n >= 1 ? n : null;
}

// [[0.1, 0.2], [0.3, 0.4]] -> '0.1 0.2|0.3 0.4'. A missing or malformed
// vector packs as '' so that topic falls back to keyword matching only.
function packVectors(vecs, count) {
  const out = [];
  for (let i = 0; i < count; i++) {
    const v = vecs && vecs[i];
    const ok = Array.isArray(v) && v.length > 0 && v.every((x) => typeof x === 'number' && Number.isFinite(x));
    out.push(ok ? v.join(' ') : '');
  }
  return out.join('|');
}

// Every input leaves as a string: queryReplacement inlines numbers UNQUOTED, and
// nullif(-75, '') then makes Postgres cast '' to integer and fail. The router
// passes chat_id as a number, so this is the live path, not an edge case.
const raw = $input.first().json;
const j = {};
for (const k of ["since","min_relevance","tag","limit","min_score","max_age_days","group_stories","item","chat_id"]) {
  j[k] = raw[k] == null ? '' : String(raw[k]).trim();
}
const item = parseItemRef(j.item);
const topics = item ? [] : parseTopics(j.tag);
// Always embed something so the flow stays linear; with no topics the vector is ignored.
const input = topics.length ? topics.map(queryText) : ['-'];
return [{ json: { ...j, item_n: item ? String(item) : '', topics, embed_body: JSON.stringify({ model: EMBED_MODEL, input }) } }];

